function BookingDetail({ booking, documents, onBack, onUpdate }: { booking: Booking; documents: DocumentItem[]; onBack: () => void; onUpdate: (booking: Booking) => void }) {
  const [toast, setToast] = useState("");
  const [reviewOpen, setReviewOpen] = useState(false);
  const [dispatchPreview, setDispatchPreview] = useState(false);
  const [previewDocument, setPreviewDocument] = useState<string | null>(null);
  const [bundlePreview, setBundlePreview] = useState(false);
  const [revisionFlag, setRevisionFlag] = useState(false);
  const [targetedNotifications, setTargetedNotifications] = useState<{ departmentCode: string; title: string; body: string }[]>([]);
  const dossierDocuments = useMemo(() => documents.map((doc) => revisionFlag && doc.id === "doc-3" ? { ...doc, state: "Revision Required" as const } : doc), [documents, revisionFlag]);
  const completion = documentCompletion(dossierDocuments);
  const departmentRows = useMemo(() => [
    { code: "DOC" as const, name: "Documentation", total: dossierDocuments.filter((doc) => doc.departmentCode === "DOC").length },
    { code: "HSE" as const, name: "HSE / Safety", total: dossierDocuments.filter((doc) => doc.departmentCode === "HSE").length },
    { code: "CRW" as const, name: "Crew Assignment", total: dossierDocuments.filter((doc) => doc.departmentCode === "CRW").length },
    { code: "ACC" as const, name: "Accounts", total: dossierDocuments.filter((doc) => doc.departmentCode === "ACC").length },
    { code: "TRN" as const, name: "Transportation", total: dossierDocuments.filter((doc) => doc.departmentCode === "TRN").length },
  ].map((row) => ({ ...row, completion: departmentCompletion(dossierDocuments, row.code) })), [dossierDocuments]);
  const canDispatch = canDispatchByRule(booking.stage, completion === 100, revisionFlag);
  const notify = (message: string) => { setToast(message); setTimeout(() => setToast(""), 2600); };
  const flagForRevision = () => { const rollback = revertBooking("All Docs Submitted", "Docs In Progress", "CRW"); const nextBooking = { ...booking, stage: rollback.stage as Stage, progress: Math.max(72, completion - 8) }; setRevisionFlag(true); setTargetedNotifications(rollback.notifications); onUpdate(nextBooking); setReviewOpen(false); notify(`Revision sent back to ${revisionReversionStage("Documentation")}; Crew Assignment and Documentation were notified.`); };
  return <div className="content"><button className="secondary-button" onClick={onBack} style={{ marginBottom: 20 }}><ArrowLeft size={14} /> Back to pipeline</button><PageHeading eyebrow="Booking dossier" title={booking.id} copy={`${booking.client} · ${booking.project} · ${booking.site}`} action={<div style={{ display: "flex", gap: 8 }}><button className="secondary-button" onClick={() => notify("Client portal link copied.")}><MessageCircle size={14} /> Client portal</button><button className="secondary-button" onClick={() => setReviewOpen(true)}><FileCheck2 size={14} /> Review docs</button><button className={`primary-button ${!canDispatch ? "secondary-button" : ""}`} disabled={!canDispatch} onClick={() => setDispatchPreview(true)}><Send size={14} /> Dispatch package</button></div>} /><div className="panel" style={{ marginBottom: 16 }}><div className="panel-header"><div><div className="panel-title">8-stage lifecycle</div><div className="panel-meta">Role-gated workflow · revisions kick the dossier back to the responsible department</div></div><StatusBadge value={booking.stage} /></div><div className="panel-body"><div style={{ display: "grid", gridTemplateColumns: "repeat(8, minmax(100px, 1fr))", gap: 6, overflowX: "auto" }}>{stages.map((stage, index) => { const active = stages.indexOf(booking.stage) >= index; return <div key={stage} style={{ minWidth: 100, opacity: active ? 1 : .48 }}><div style={{ display: "flex", alignItems: "center", gap: 6, color: active ? "#f1f1f1" : "#777", fontSize: 10, lineHeight: 1.3 }}><div style={{ width: 22, height: 22, borderRadius: "50%", display: "grid", placeItems: "center", background: active ? "#e31e24" : "#292929", color: active ? "#fff" : "#777", flex: "none" }}>{active ? <Check size={12} /> : index + 1}</div>{stage}</div>{index < stages.length - 1 && <div style={{ height: 2, background: active ? "#8e272b" : "#2b2b2b", margin: "10px 0 0 22px" }} />}</div>; })}</div></div></div><div className="detail-grid"><div><div className="panel"><div className="panel-header"><div className="panel-title">Dossier details</div><StatusBadge value={booking.priority} /></div><div className="panel-body"><div className="detail-list"><div className="detail-cell"><label>Client</label><div>{booking.client}</div></div><div className="detail-cell"><label>Project Manager</label><div>{booking.pm}</div></div><div className="detail-cell"><label>Mobilization</label><div>{booking.mob}</div></div><div className="detail-cell"><label>Off-hire</label><div>{booking.offHire}</div></div><div className="detail-cell"><label>Crane</label><div>{booking.crane}</div></div><div className="detail-cell"><label>Site location</label><div>{booking.site}</div></div></div></div></div><div className="panel" style={{ marginTop: 16 }}><div className="panel-header"><div><div className="panel-title">Assigned crew</div><div className="panel-meta">Live availability and certificate status</div></div><button className="secondary-button">Edit assignment</button></div><div className="panel-body"><div className="resource-grid">{crews.slice(0, 4).map((crew) => <div className="resource-card selected" key={crew.name}><div style={{ display: "flex", gap: 9, alignItems: "center" }}><div className="avatar">{crew.initials}</div><div><div className="resource-name">{crew.name}</div><div className="resource-sub">{crew.role}</div></div></div><div style={{ marginTop: 9, display: "flex", justifyContent: "space-between", alignItems: "center" }}><StatusBadge value={crew.availability} />{crew.flag && <StatusBadge value="Training required" />}</div></div>)}</div></div></div></div><div><div className="panel"><div className="panel-header"><div><div className="panel-title">Document completion</div><div className="panel-meta">All department uploads in parallel</div></div><div style={{ fontSize: 22, fontWeight: 750 }}>{completion}%</div></div><div className="panel-body"><div className="progress-track" style={{ height: 10 }}><div className={`progress-fill ${completion === 100 ? "green" : ""}`} style={{ width: `${completion}%` }} /></div><div className="compliance-list" style={{ marginTop: 13 }}>{departmentRows.map((row) => <div className="compliance-row" key={row.code}><div><div className="compliance-name">{row.name}</div><div className="compliance-sub">{row.completion}% complete · {row.total} required item{row.total === 1 ? "" : "s"}</div></div><StatusBadge value={row.completion === 100 ? "Complete" : row.completion === 0 ? "Pending" : "In progress"} /></div>)}</div></div></div><div className="panel" style={{ marginTop: 16 }}><div className="panel-header"><div className="panel-title">Drive archive</div><FolderOpen size={15} color="#69d495" /></div><div className="panel-body"><div className="locked-input"><span>Bk {booking.client}-Dubai Downtown-11.08.2026</span><StatusBadge value="Synced" /></div><div className="compliance-sub" style={{ marginTop: 9 }}>All uploaded documents are mirrored to the booking folder.</div></div></div><div className="panel" style={{ marginTop: 16 }}><div className="panel-header"><div className="panel-title">Dispatch recipient</div><Lock size={15} color="#f2b94b" /></div><div className="panel-body"><div className="locked-input"><span>operations@gulfcontracting.ae</span><span style={{ color: "#777" }}>Locked</span></div><div className="compliance-sub" style={{ marginTop: 9 }}>The client email is immutable after Sales confirmation.</div></div></div></div></div>{targetedNotifications.length > 0 && <div className="panel" style={{ marginTop: 16 }}><div className="panel-header"><div><div className="panel-title">Targeted notifications</div><div className="panel-meta">Lifecycle event delivery log</div></div><StatusBadge value={`${targetedNotifications.length} queued`} /></div><div className="panel-body"><div className="notification-stack">{targetedNotifications.map((notification, index) => <div className="notification" key={`${notification.departmentCode}-${index}`}><div className="title">{notification.departmentCode} · {notification.title}</div><div className="body">{notification.body} · in-app + email</div></div>)}</div></div></div>}{previewDocument && <div style={{ position: "fixed", inset: 0, zIndex: 50, background: "rgba(0,0,0,.78)", display: "grid", placeItems: "center", padding: 20 }}><div className="panel" style={{ width: "min(680px, 100%)" }}><div className="panel-header"><div><div className="panel-title">Document preview</div><div className="panel-meta">{previewDocument} · approved submission</div></div><button className="icon-button" onClick={() => setPreviewDocument(null)}><X size={15} /></button></div><div className="panel-body"><div style={{ minHeight: 280, border: "1px solid #303030", borderRadius: 8, background: "linear-gradient(135deg, #242424, #151515)", display: "grid", placeItems: "center", textAlign: "center", padding: 30 }}><div><FileText size={40} color="#e31e24" style={{ marginBottom: 12 }} /><div style={{ fontSize: 16, fontWeight: 750, color: "#fff" }}>{previewDocument}</div><div className="page-copy" style={{ margin: "8px auto 0" }}>Secure preview surface · file integrity verified · mirrored to the booking Drive folder.</div><div className="status-badge green" style={{ marginTop: 16 }}><CheckCircle2 size={10} /> Approved document</div></div></div></div></div></div>}{reviewOpen && <div style={{ position: "fixed", inset: 0, zIndex: 40, background: "rgba(0,0,0,.72)", display: "grid", placeItems: "center", padding: 20 }}><div className="panel" style={{ width: "min(720px, 100%)", maxHeight: "85vh", overflow: "auto" }}><div className="panel-header"><div><div className="panel-title">Document review · {booking.id}</div><div className="panel-meta">Preview submitted files before moving the dossier to Reviewed.</div></div><button className="icon-button" onClick={() => setReviewOpen(false)}><X size={15} /></button></div><div className="panel-body"><div className="compliance-list">{dossierDocuments.map((doc) => <div className="compliance-row" key={doc.id}><div style={{ display: "flex", gap: 9, alignItems: "center" }}><FileText size={15} color="#888" /><div><div className="compliance-name">{doc.name}</div><div className="compliance-sub">{doc.departmentCode} · Required · preview available</div></div></div><div style={{ display: "flex", gap: 7, alignItems: "center" }}><StatusBadge value={doc.state === "Revision Required" ? "Revision" : doc.state} /><button className="secondary-button" onClick={() => setPreviewDocument(doc.name)}>Preview</button></div></div>)}</div><div className="wizard-actions"><button className="secondary-button" onClick={flagForRevision}><AlertTriangle size={14} /> Flag for revision</button><button className="primary-button" onClick={() => { const approval = transitionBooking("All Docs Submitted", "Reviewed", "Salesperson"); const nextBooking = { ...booking, stage: approval.stage as Stage, progress: 100 }; setTargetedNotifications(approval.notifications); onUpdate(nextBooking); setReviewOpen(false); notify("All submitted documents approved. Dossier is now Reviewed."); }}><CheckCircle2 size={14} /> Approve dossier</button></div></div></div></div>}{dispatchPreview && <div style={{ position: "fixed", inset: 0, zIndex: 40, background: "rgba(0,0,0,.72)", display: "grid", placeItems: "center", padding: 20 }}><div className="panel" style={{ width: "min(760px, 100%)", maxHeight: "85vh", overflow: "auto" }}><div className="panel-header"><div><div className="panel-title">Dispatch package preview</div><div className="panel-meta">Locked recipient · operations@gulfcontracting.ae</div></div><button className="icon-button" onClick={() => setDispatchPreview(false)}><X size={15} /></button></div><div className="panel-body"><div className="notification"><div className="title"><Mail size={14} style={{ verticalAlign: "-2px", marginRight: 6 }} />BOB Cranes · Final document package</div><div className="body">The email will include the approved PDF bundle, crew manifest, and Drive archive link.</div></div><div className="detail-list" style={{ marginTop: 14 }}><div className="detail-cell"><label>Recipient</label><div>operations@gulfcontracting.ae</div></div><div className="detail-cell"><label>Subject</label><div>BOB Booking-31511 · Dispatch package</div></div><div className="detail-cell"><label>Bundle</label><div>6 approved documents · PDF</div></div><div className="detail-cell"><label>Drive archive</label><div>Bk Gulf Contracting LLC-Dubai Downtown-11.08.2026</div></div></div><div className="panel" style={{ marginTop: 14, background: "#101010" }}><div className="panel-header"><div className="panel-title">Crew manifest</div><span className="panel-meta">200T Mobile Crane</span></div><div className="panel-body"><table className="data-table"><thead><tr><th>Name</th><th>Designation</th><th>Compliance</th></tr></thead><tbody>{crews.slice(0, 4).map((crew) => <tr key={crew.name}><td><strong>{crew.name}</strong></td><td>{crew.role}</td><td><StatusBadge value="Approved" /></td></tr>)}</tbody></table></div></div><div className="wizard-actions"><button className="secondary-button" onClick={() => setBundlePreview(true)}><FileText size={14} /> Preview PDF bundle</button><button className="primary-button" onClick={() => { setDispatchPreview(false); notify("Final package emailed to the locked notification email."); }}><Send size={14} /> Send final package</button></div></div></div></div>}{bundlePreview && <div style={{ position: "fixed", inset: 0, zIndex: 50, background: "rgba(0,0,0,.78)", display: "grid", placeItems: "center", padding: 20 }}><div className="panel" style={{ width: "min(820px, 100%)", maxHeight: "85vh", overflow: "auto" }}><div className="panel-header"><div><div className="panel-title">PDF bundle preview</div><div className="panel-meta">BOB Booking-31511 · 6 approved files</div></div><button className="icon-button" onClick={() => setBundlePreview(false)}><X size={15} /></button></div><div className="panel-body"><div className="detail-list"><div className="detail-cell"><label>Cover page</label><div>BOB Cranes dispatch dossier</div></div><div className="detail-cell"><label>Crew manifest</label><div>4 compliant crew members</div></div><div className="detail-cell"><label>Attachments</label><div>Method statement · lift plan · LPO · certificates</div></div><div className="detail-cell"><label>Archive</label><div>Google Drive folder synced</div></div></div><div style={{ marginTop: 14, minHeight: 130, border: "1px solid #303030", borderRadius: 8, background: "#111", padding: 18 }}><div className="eyebrow">BOB CRANES · FINAL DISPATCH PACKAGE</div><div style={{ fontSize: 18, fontWeight: 750 }}>Gulf Contracting LLC</div><div className="page-copy">200T Mobile Crane · Dubai Downtown · 11 Aug 2026</div><div className="compliance-sub" style={{ marginTop: 18 }}>This preview represents the PDF bundle that will be emailed to the locked notification address.</div></div></div></div></div>}{toast && <div className="toast-note"><CheckCircle2 size={14} style={{ verticalAlign: "-2px", marginRight: 7 }} />{toast}</div>}</div>;
}

type ClientPortalProps = {
  booking: Booking;
  documents: DocumentItem[];
  onUpdate: (booking: Booking) => void;
  onUploadAll: () => void;
  onBackToInternal: () => void;
};

function ClientPortal({ booking, documents, onUpdate, onUploadAll, onBackToInternal }: ClientPortalProps) {
  const [tab, setTab] = useState<"summary" | "documents" | "chat">("summary");
  const [message, setMessage] = useState("");
  const [uploadToast, setUploadToast] = useState("");
  const [messages, setMessages] = useState([
    { from: "Documentation", text: "Welcome to your BOB Cranes response portal. Please upload the signed site access pass when ready.", time: "09:42" },
    { from: "You", text: "Thanks. We will share the updated LPO before close of business.", time: "09:47" },
  ]);
  const pendingDocs = documents.filter((doc) => doc.state === "Required");
  const uploadedDocs = documents.length - pendingDocs.length;
  const progress = pendingDocs.length === 0 ? 100 : Math.max(booking.progress, Math.round((uploadedDocs / documents.length) * 100));
  const sendMessage = () => { if (!message.trim()) return; setMessages((current) => [...current, { from: "You", text: message, time: "Now" }]); setMessage(""); };
  const notify = (text: string) => { setUploadToast(text); setTimeout(() => setUploadToast(""), 2800); };
  const uploadBatch = () => {
    onUploadAll();
    notify("Batch upload accepted across Documentation, HSE, Accounts, and Transportation.");
  };
  const submitDocuments = () => {
    if (pendingDocs.length > 0) return;
    onUpdate({ ...booking, stage: "All Docs Submitted", progress: 100 });
    setTab("summary");
    notify("All documents submitted. Sales review is now required before dispatch.");
  };
  const reviewReady = booking.stage === "All Docs Submitted" || booking.stage === "Reviewed" || booking.stage === "Dispatched";
  return <div className="client-shell"><header className="client-topbar"><div className="brand-row"><div className="brand-mark">B</div><div><div className="brand-title">BOB CRANES</div><div className="brand-subtitle">Client response portal</div></div></div><div style={{ display: "flex", alignItems: "center", gap: 9 }}><span className="status-badge green"><ShieldCheck size={10} /> Secure portal</span><div className="avatar">GC</div></div></header><main className="client-content"><div className="client-hero"><div><div className="eyebrow">BOB Booking-31511</div><h1 className="client-title">Gulf Contracting LLC</h1><p className="page-copy">Downtown Tower Lift · 200T Mobile Crane · Dubai Downtown</p></div><div style={{ textAlign: "right" }}><StatusBadge value={booking.stage} /><div className="compliance-sub" style={{ marginTop: 8 }}>Mobilization · 11 Aug 2026</div></div></div><div className="client-tabs"><button className={`client-tab ${tab === "summary" ? "active" : ""}`} onClick={() => setTab("summary")}>Booking summary</button><button className={`client-tab ${tab === "documents" ? "active" : ""}`} onClick={() => setTab("documents")}>Required documents <span className="status-badge amber" style={{ marginLeft: 5, padding: "2px 6px" }}>{pendingDocs.length}</span></button><button className={`client-tab ${tab === "chat" ? "active" : ""}`} onClick={() => setTab("chat")}>Team chat</button></div>{tab === "summary" && <div className="client-grid"><div className="panel"><div className="panel-header"><div><div className="panel-title">Your booking progress</div><div className="panel-meta">BOB Cranes team is coordinating your submission</div></div><div style={{ fontSize: 20, fontWeight: 750 }}>{progress}%</div></div><div className="panel-body"><div className="progress-track" style={{ height: 11 }}><div className={`progress-fill ${progress === 100 ? "green" : ""}`} style={{ width: `${progress}%` }} /></div><div className="compliance-list" style={{ marginTop: 13 }}>{["Booking confirmed", "Crane and crew assigned", "Lifting gear confirmed", "Documents in progress", "Final review & dispatch"].map((item, index) => { const complete = index < 3 || (index === 3 && progress === 100); const inProgress = index === 3 && progress < 100; const reviewed = booking.stage === "Reviewed" || booking.stage === "Dispatched"; return <div className="compliance-row" key={item}><div style={{ display: "flex", gap: 10, alignItems: "center" }}><div className="avatar" style={{ width: 24, height: 24, background: complete ? "#214f34" : "#292929" }}>{complete ? <Check size={12} /> : inProgress ? <Clock3 size={12} /> : <Lock size={11} />}</div><div className="compliance-name">{item}</div></div><div className="compliance-sub">{complete ? "Complete" : reviewed && index === 4 ? "Ready" : inProgress ? "In progress" : reviewReady && index === 4 ? "Sales review" : "Upcoming"}</div></div>; })}</div>{reviewReady && <div className="notification" style={{ marginTop: 14 }}><div className="title">100% documents submitted</div><div className="body">The dossier is in the Sales review queue. Dispatch remains role-gated until Sales approves the final bundle.</div></div>}{reviewReady && <button className="secondary-button" style={{ marginTop: 12 }} onClick={onBackToInternal}><ArrowLeft size={14} /> Return to internal review</button>}</div></div><div className="panel"><div className="panel-header"><div className="panel-title">Assigned crew</div><Users size={15} color="#888" /></div><div className="panel-body">{crews.slice(0, 4).map((crew) => <div className="activity-item" key={crew.name}><div className="avatar">{crew.initials}</div><div><div className="activity-text"><strong>{crew.name}</strong></div><div className="activity-time">{crew.role}</div></div></div>)}</div></div></div>}{tab === "documents" && <div className="client-grid"><div className="panel"><div className="panel-header"><div><div className="panel-title">Required from your team</div><div className="panel-meta">Accepted formats: PDF, JPG, PNG · max 25MB</div></div><button className="primary-button" onClick={uploadBatch} disabled={pendingDocs.length === 0}>{pendingDocs.length === 0 ? <CheckCircle2 size={14} /> : <CloudUpload size={14} />}{pendingDocs.length === 0 ? "All uploaded" : "Upload remaining"}</button></div><div className="panel-body"><div className="notification" style={{ marginBottom: 14 }}><div className="title">{uploadedDocs}/{documents.length} requirements uploaded · {progress}% tracked</div><div className="body">This demo batch maps uploads to their owning departments and mirrors the Drive archive.</div></div><div className="compliance-list">{documents.map((doc) => <div className="compliance-row" key={doc.name}><div style={{ display: "flex", gap: 10, alignItems: "center" }}><FileText size={16} color="#888" /><div><div className="compliance-name">{doc.name}</div><div className="compliance-sub">{doc.departmentCode} · client upload · synced to Drive</div></div></div><StatusBadge value={doc.state} /></div>)}</div>{pendingDocs.length === 0 && booking.stage === "Docs In Progress" && <button className="primary-button" style={{ marginTop: 16 }} onClick={submitDocuments}><CheckCircle2 size={14} /> Submit all documents</button>}{booking.stage === "All Docs Submitted" && <div className="notification" style={{ marginTop: 16 }}><div className="title">All Docs Submitted</div><div className="body">Sales has been notified. Open internal review to approve and unlock the dispatch package.</div></div>}</div></div><div className="panel"><div className="panel-header"><div className="panel-title">Need help?</div><MessageCircle size={15} color="#888" /></div><div className="panel-body"><p className="page-copy" style={{ marginTop: 0 }}>Chat with a BOB Cranes team member about your booking. Messages are routed to the right department.</p><div className="filter-row" style={{ marginTop: 14 }}>{["Documentation", "HSE", "Sales", "Accounts", "Operations"].map((team) => <span className="status-badge gray" key={team}>{team}</span>)}</div><button className="secondary-button" style={{ marginTop: 18 }} onClick={() => setTab("chat")}><MessageCircle size={14} /> Open team chat</button></div></div></div>}{tab === "chat" && <div className="client-grid"><div className="panel"><div className="panel-header"><div><div className="panel-title">Your BOB Cranes team</div><div className="panel-meta">Responses are visible to assigned internal teams</div></div><StatusBadge value="5 teams connected" /></div><div className="panel-body"><div className="chat-window">{messages.map((item, index) => <div className={`chat-message ${item.from === "You" ? "outgoing" : ""}`} key={`${item.time}-${index}`}><div className="avatar">{item.from === "You" ? "GC" : "BOB"}</div><div><div className="chat-from">{item.from} · {item.time}</div><div className="chat-bubble">{item.text}</div></div></div>)}</div><div className="chat-input-row"><input className="form-input" placeholder="Write a message to the BOB team..." value={message} onChange={(event) => setMessage(event.target.value)} onKeyDown={(event) => event.key === "Enter" && sendMessage()} /><button className="primary-button" onClick={sendMessage}><Send size={14} /></button></div></div></div><div className="panel"><div className="panel-header"><div className="panel-title">Routing directory</div><Users size={15} color="#888" /></div><div className="panel-body"><div className="compliance-list">{["Documentation", "HSE", "Sales", "Accounts", "Operations Management"].map((team, index) => <div className="compliance-row" key={team}><div style={{ display: "flex", gap: 10, alignItems: "center" }}><div className="avatar" style={{ background: ["#462225", "#22384d", "#493a1b", "#2d234b", "#214b35"][index] }}>{team[0]}</div><div><div className="compliance-name">{team}</div><div className="compliance-sub">{index === 0 ? "Primary coordinator" : "Available for questions"}</div></div></div><StatusBadge value="Online" /></div>)}</div></div></div></div>}{uploadToast && <div className="toast-note"><CheckCircle2 size={14} style={{ verticalAlign: "-2px", marginRight: 7 }} />{uploadToast}</div>}</main></div>;
}
function AttendanceView({ records, setRecords, selectedDate, setSelectedDate }: { records: Record<string, AttendanceRecord>; setRecords: React.Dispatch<React.SetStateAction<Record<string, AttendanceRecord>>>; selectedDate: string; setSelectedDate: React.Dispatch<React.SetStateAction<string>> }) {
  const today = dateKey(new Date());
  const baseRecord = defaultAttendanceRecord(attendanceRoster);
  const record = records[selectedDate] ?? (selectedDate === today ? baseRecord : historicalAttendanceRecord(baseRecord));
  const summary = summarizeAttendance(record);
  const marked = attendanceCompletion(record, attendanceRoster.length);
  const updateStatus = (employeeName: string, status: AttendanceStatus) => setRecords((current) => ({ ...current, [selectedDate]: updateAttendance(record, employeeName, status) }));
  const markAllPresent = () => setRecords((current) => ({ ...current, [selectedDate]: Object.fromEntries(attendanceRoster.map((employee) => [employee.name, "Present"])) as AttendanceRecord }));
  const goPrevious = () => setSelectedDate((current) => shiftDate(current, -1));
  const goNext = () => setSelectedDate((current) => current < today ? shiftDate(current, 1) : current);
  return <div className="content"><PageHeading eyebrow="People operations" title="Attendance" copy="Mark daily attendance for every employee and review previous days without leaving the operations workspace." action={<button className="primary-button" onClick={markAllPresent}><CheckCircle2 size={14} /> Mark all present</button>} /><div className="attendance-toolbar panel"><div className="attendance-date-controls"><button className="icon-button attendance-nav" onClick={goPrevious} aria-label="Previous day"><ArrowLeft size={15} /></button><div><div className="panel-title">{formatAttendanceDate(selectedDate)}</div><div className="panel-meta">{selectedDate === today ? "Today · editable attendance" : "Historical record · editable review"}</div></div><button className="icon-button attendance-nav" onClick={goNext} disabled={selectedDate >= today} aria-label="Next day"><ArrowRight size={15} /></button>{selectedDate !== today && <button className="secondary-button attendance-today" onClick={() => setSelectedDate(today)}>Today</button>}</div><StatusBadge value={selectedDate === today ? "Current day" : "History"} /></div><div className="attendance-summary-grid"><MetricCard label="Marked" value={`${marked}%`} foot={`${attendanceRoster.length} employees`} icon={<ClipboardCheck size={13} />} tone="green" /><MetricCard label="Present" value={`${summary.Present}`} foot="On duty today" icon={<CheckCircle2 size={13} />} tone="green" /><MetricCard label="On leave" value={`${summary["On Leave"]}`} foot="Approved leave" icon={<CalendarDays size={13} />} /><MetricCard label="Assigned / off-site" value={`${summary.Assigned + summary["Off-Site"]}`} foot="Away from base" icon={<Users size={13} />} /></div><div className="panel attendance-panel"><div className="panel-header"><div><div className="panel-title">Employee attendance</div><div className="panel-meta">Set one status per employee for {formatAttendanceDate(selectedDate)}.</div></div><div className="panel-meta">{attendanceRoster.length} roster members</div></div><div className="panel-body"><div className="attendance-list">{attendanceRoster.map((employee) => { const status = record[employee.name] ?? "Present"; return <div className="attendance-row" key={employee.name}><div className="attendance-person"><div className="avatar">{employee.initials}</div><div><div className="compliance-name">{employee.name}</div><div className="compliance-sub">{employee.role}</div></div></div><div className="attendance-action"><StatusBadge value={status} /><select className="attendance-select" value={status} onChange={(event) => updateStatus(employee.name, event.target.value as AttendanceStatus)} aria-label={`Attendance for ${employee.name}`}>{ATTENDANCE_STATUSES.map((option) => <option value={option} key={option}>{option}</option>)}</select></div></div>; })}</div></div></div><div className="attendance-note"><ShieldCheck size={15} /><span>Attendance changes are kept in this dashboard session and can be reviewed by moving back through the date controls.</span></div></div>;
}

function DepartmentView({ department, bookings, setDetail }: { department: string; bookings: Booking[]; setDetail: (booking: Booking) => void }) {
  const focus = department.includes("Sales") ? "Client intake, LPO verification, and dispatch review" : department.includes("Documentation") ? "Dossier control, permit packs, and revision queues" : department.includes("Lifting") ? "Gear inspection certificates and selection gates" : department.includes("HSE") ? "Lift plans, risk controls, and safety approvals" : department.includes("Accounts") ? "Commercial documents, invoices, and release controls" : department.includes("Crew") ? "Workmen availability, certifications, and assignment" : department.includes("Transportation") ? "Trailers, delivery notes, and site movement" : "Department queue, compliance actions, and operational readiness";
  const queue = bookings.filter((booking) => booking.progress < 100).slice(0, 4);
  return <div className="content"><PageHeading eyebrow="Department workspace" title={department} copy={focus} action={<button className="primary-button" onClick={() => setDetail(bookings[0])}><ClipboardCheck size={14} /> Open priority dossier</button>} /><div className="metric-grid"><MetricCard label="Open queue" value={`${queue.length + 4}`} foot="Needs action today" icon={<Clock3 size={13} />} /><MetricCard label="Ready to clear" value="03" foot="Awaiting owner review" icon={<CheckCircle2 size={13} />} tone="green" /><MetricCard label="Compliance watch" value="06" foot="Certificates due soon" icon={<AlertTriangle size={13} />} /><MetricCard label="Notifications" value="08" foot="In-app + email delivered" icon={<Bell size={13} />} /></div><div className="detail-grid"><div className="panel"><div className="panel-header"><div><div className="panel-title">Department action queue</div><div className="panel-meta">Booking dossiers currently requiring {department.toLowerCase()} attention</div></div><StatusBadge value="Live queue" /></div><div className="panel-body"><div className="compliance-list">{queue.map((booking) => <button className="compliance-row" key={booking.id} onClick={() => setDetail(booking)} style={{ width: "100%", textAlign: "left", background: "transparent", border: 0, color: "inherit" }}><div><div className="compliance-name">{booking.id} · {booking.client}</div><div className="compliance-sub">{booking.crane} · {booking.site}</div></div><div style={{ display: "flex", gap: 8, alignItems: "center" }}><span className="status-badge gray">{booking.progress}%</span><ArrowRight size={14} color="#777" /></div></button>)}</div></div></div><div className="panel"><div className="panel-header"><div className="panel-title">Working procedure</div><ShieldCheck size={15} color="#69d495" /></div><div className="panel-body"><div className="notification-stack"><div className="notification"><div className="title">1 · Receive assignment</div><div className="body">A role-gated notification lands in the department queue.</div></div><div className="notification"><div className="title">2 · Validate evidence</div><div className="body">Review documents, certificates, and site-specific requirements.</div></div><div className="notification"><div className="title">3 · Submit and hand off</div><div className="body">Complete the department checklist to move the dossier forward.</div></div></div></div></div></div></div>;
}

export default function Home() {
  const [location, setLocation] = useLocation();
  const { user, logout } = useAuth();
  const [view, setView] = useState<View>(() => location === "/uploads" ? "uploads" : location === "/attendance" ? "attendance" : "overview");
  const [bookings, setBookings] = useState<Booking[]>(initialBookings);
  const [uploadDocuments, setUploadDocuments] = useState<DocumentItem[]>(initialUploadDocuments);
  const [attendanceRecords, setAttendanceRecords] = useState<Record<string, AttendanceRecord>>({});
  const [selectedAttendanceDate, setSelectedAttendanceDate] = useState(() => dateKey(new Date()));
  const [uploadRecords, setUploadRecords] = useState<UploadMap>({});
  const [activeBooking, setActiveBooking] = useState<Booking | null>(null);
  const [activeDepartment, setActiveDepartment] = useState<string | null>(null);
  const updateBooking = (nextBooking: Booking) => { setBookings((current) => current.map((item) => item.id === nextBooking.id ? nextBooking : item)); setActiveBooking(nextBooking); };
  const isClient = location.startsWith("/client");
  const groupedCount = useMemo(() => bookings.length, [bookings.length]);
  const clientBooking = bookings.find((booking) => booking.id === "BOB Booking-31511") ?? bookings[0];
  if (isClient && clientBooking) return <ClientPortal booking={clientBooking} documents={uploadDocuments} onUpdate={updateBooking} onUploadAll={() => setUploadDocuments((current) => current.map((doc) => doc.state === "Required" ? { ...doc, state: "Uploaded" } : doc))} onBackToInternal={() => setLocation("/")} />;
  const openDetail = (booking: Booking) => { setActiveBooking(booking); setView("detail"); };
  const createBooking = (booking: Booking) => { setBookings((current) => [booking, ...current]); setActiveBooking(booking); setView("detail"); };
  const openDepartment = (department: string) => { const departmentCode = DEPARTMENT_LABEL_TO_CODE[department]; if (!user || (user.role !== "admin" && user.departmentCode !== departmentCode)) return; setActiveDepartment(department); setActiveBooking(null); setView("department"); };
  const signOut = async () => { await logout(); setLocation("/login"); };
  const canView = (nextView: View) => canAccessWorkspaceView(user ?? { role: "user", departmentCode: null }, nextView);
  useEffect(() => { if (user && !canView(view)) setView("overview"); }, [user, view]);
  if (!user) return null;
  const guardedSetView = (nextView: View) => { setActiveBooking(null); setActiveDepartment(null); setView(canView(nextView) ? nextView : "overview"); };
  return <Shell view={view} setView={guardedSetView} onClient={() => setLocation("/client/portal-bob-31511")} onDepartment={openDepartment} departmentLabel={activeDepartment} user={user} onSignOut={signOut}>
    {view === "overview" && <Overview bookings={bookings} documents={uploadDocuments} setView={guardedSetView} setDetail={openDetail} attendanceRecords={attendanceRecords} setAttendanceRecords={setAttendanceRecords} user={user} />}
    {view === "bookings" && user.role === "admin" && <BookingsView bookings={bookings} setView={guardedSetView} setDetail={openDetail} />}
    {view === "wizard" && (user.role === "admin" || user.departmentCode === "sales") && <Wizard onCreated={createBooking} onCancel={() => guardedSetView("overview")} />}
    {view === "docs" && (user.role === "admin" || user.departmentCode === "documentation" || user.departmentCode === "hse") && <DocsView bookings={bookings} setDetail={openDetail} />}
    {view === "crew" && (user.role === "admin" || user.departmentCode === "crew") && <CrewView />}
    {view === "gear" && (user.role === "admin" || user.departmentCode === "lifting-gears") && <GearView />}
    {view === "attendance" && (user.role === "admin" || user.departmentCode === "hr") && <AttendanceView records={attendanceRecords} setRecords={setAttendanceRecords} selectedDate={selectedAttendanceDate} setSelectedDate={setSelectedAttendanceDate} />}
    {view === "uploads" && (user.role === "admin" || user.departmentCode === "accounts") && <DataUploadCenter uploads={uploadRecords} setUploads={setUploadRecords} />}
    {view === "users" && user.role === "admin" && <DepartmentUsersView />}
    {view === "department" && activeDepartment && <DepartmentView department={activeDepartment} bookings={bookings} setDetail={openDetail} />}
    {view === "detail" && activeBooking && <BookingDetail booking={activeBooking} documents={uploadDocuments} onUpdate={updateBooking} onBack={() => { setActiveBooking(null); setView("overview"); }} />}
    <div style={{ color: "#555", fontSize: 10, textAlign: "right", padding: "10px 0 0" }}>System status: operational · {groupedCount} dossiers in view · v3.0</div>
  </Shell>;
}
